mkdir -p /work/postgres; cd /work/postgres
cat > schema.sql <<'EOF'
-- PostgreSQL DDL translated from oracle/sp_customer_tier.sql and oracle/sp_monthly_report.sql
-- Type mapping: NUMBER (integer ids/counts) -> bigint, NUMBER(p,s) -> numeric(p,s),
--               VARCHAR2(n) -> varchar(n), DATE -> timestamptz

CREATE TABLE customers (
    customer_id   bigint PRIMARY KEY,
    customer_name varchar(120) NOT NULL,
    status        varchar(20)  DEFAULT 'ACTIVE'
);

CREATE TABLE orders (
    order_id    bigint PRIMARY KEY,
    customer_id bigint NOT NULL,
    order_total numeric(12,2) NOT NULL,
    order_date  timestamptz NOT NULL
);

CREATE TABLE customer_tiers (
    customer_id    bigint PRIMARY KEY,
    customer_name  varchar(120),
    total_spend    numeric(12,2),
    order_count    bigint,
    tier           varchar(20),
    computed_at    timestamptz
);

CREATE SEQUENCE seq_tier_id START WITH 1 INCREMENT BY 1;

CREATE TABLE products (
    product_id   bigint PRIMARY KEY,
    product_name varchar(120),
    category     varchar(60)
);

CREATE TABLE order_items (
    order_item_id bigint PRIMARY KEY,
    order_id      bigint,
    product_id    bigint,
    quantity      numeric,
    unit_price    numeric(10,2)
);

CREATE TABLE monthly_report (
    report_month   varchar(7),
    category       varchar(60),
    revenue        numeric(12,2),
    units_sold     numeric
);
EOF
cat > procedures.sql <<'EOF'
-- PostgreSQL plpgsql translations of the Oracle procedures.
--
-- Notes on the translation:
--  * NVL -> COALESCE, sysdate -> now(), column-anchored declarations replaced by
--    explicit types, Oracle "FROM DUAL" selects become plain expressions.
--  * Transaction control: a CALL issued in autocommit mode commits on completion,
--    which matches the Oracle COMMIT. Explicit COMMIT/ROLLBACK are omitted so the
--    procedures also work when called inside an outer transaction, and because
--    plpgsql forbids COMMIT/ROLLBACK inside a block that has an EXCEPTION clause.
--    The EXCEPTION clause itself rolls back the block's work (subtransaction),
--    which reproduces the Oracle ROLLBACK in the handlers.
--  * Rows are inserted in a deterministic order (the Oracle GROUP BY order is
--    unspecified); readers should still ORDER BY when they need a fixed order.

CREATE OR REPLACE PROCEDURE sp_customer_tier()
LANGUAGE plpgsql
AS $$
DECLARE
    rec      record;
    v_tier   varchar(20);
    v_status varchar(20);
BEGIN
    DELETE FROM customer_tiers;

    FOR rec IN
        SELECT o.customer_id,
               c.customer_name,
               SUM(o.order_total) AS total_spend,
               COUNT(*)           AS order_count
        FROM   orders o
        JOIN   customers c ON c.customer_id = o.customer_id
        WHERE  COALESCE(c.status, 'ACTIVE') = 'ACTIVE'
        GROUP  BY o.customer_id, c.customer_name
        ORDER  BY total_spend, o.customer_id
    LOOP
        IF rec.total_spend >= 1000 THEN
            v_tier := 'GOLD';
        ELSIF rec.total_spend >= 500 THEN
            v_tier := 'SILVER';
        ELSE
            v_tier := 'BRONZE';
        END IF;

        INSERT INTO customer_tiers
            (customer_id, customer_name, total_spend, order_count, tier, computed_at)
        VALUES
            (rec.customer_id, rec.customer_name, rec.total_spend, rec.order_count,
             v_tier, now());
    END LOOP;

    -- Oracle: SELECT status INTO v_status FROM customers WHERE <first row>
    -- (raised NO_DATA_FOUND on an empty table; STRICT keeps that behaviour).
    SELECT status INTO STRICT v_status FROM customers LIMIT 1;
END;
$$;

CREATE OR REPLACE PROCEDURE sp_monthly_report(p_month varchar)
LANGUAGE plpgsql
AS $$
DECLARE
    rec            record;
    v_report_month varchar(7);
    v_category     varchar(60);
    v_revenue      numeric(12,2);
    v_units_sold   numeric;
    v_has_data     numeric := 0;
BEGIN
    -- Oracle: SELECT COUNT(*) INTO v_has_data FROM DUAL  (always 1)
    v_has_data := 1;

    DELETE FROM monthly_report WHERE report_month = p_month;

    FOR rec IN
        SELECT p.category                                    AS category,
               COALESCE(SUM(oi.quantity * oi.unit_price), 0) AS revenue,
               COALESCE(SUM(oi.quantity), 0)                 AS units_sold
        FROM   order_items oi
        JOIN   products p ON p.product_id = oi.product_id
        GROUP  BY p.category
        ORDER  BY revenue DESC, p.category
    LOOP
        v_report_month := p_month;
        v_category     := rec.category;
        v_revenue      := rec.revenue;
        v_units_sold   := rec.units_sold;

        INSERT INTO monthly_report
            (report_month, category, revenue, units_sold)
        VALUES
            (v_report_month, v_category, v_revenue, v_units_sold);
    END LOOP;

    IF v_has_data = 0 THEN
        -- user-defined exception e_no_data
        RAISE EXCEPTION 'no data for month %', p_month USING ERRCODE = 'P0100';
    END IF;
EXCEPTION
    WHEN SQLSTATE 'P0100' THEN
        -- e_no_data: work of this block is rolled back, swallow the error
        NULL;
    WHEN OTHERS THEN
        RAISE;
END;
$$;
EOF
cd /work
psql -qc "DROP DATABASE IF EXISTS migtest" -c "CREATE DATABASE migtest"
export PGDATABASE=migtest
psql -v ON_ERROR_STOP=1 -q -f postgres/schema.sql -f postgres/procedures.sql -f seed.sql && \
psql -v ON_ERROR_STOP=1 -q -c "CALL sp_customer_tier()" -c "CALL sp_monthly_report('2026-09')"
psql --csv -c "SELECT customer_id,customer_name,total_spend,order_count,tier FROM customer_tiers" | diff - expected/output.csv && echo TIER OK
psql --csv -c "SELECT report_month,category,revenue,units_sold FROM monthly_report" | diff - expected/output_monthly.csv && echo MONTHLY OK
grep -niE 'DUAL|NVL\(|ROWNUM|\(\+\)|VARCHAR2|sysdate|%ROWTYPE|%TYPE' postgres/*.sql

